45		if err != nil {
46			return nil, err
47		}
48	
49		usernamesByID := make(map[int32]string, len(usersByID))
50		for _, user := range usersByID {
51			usernamesByID[user.ID] = user.Username
52		}
53		return usernamesByID, nil
54	}
